import re
import sys


def calc(expr: str) -> int | str:
    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)

    tokens = re.findall(r"\d+|[-+*/%^()]", expr)
    n = len(tokens)
    pos = 0

    def peek():
        return tokens[pos] if pos < n else None

    def take():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def power(a, b):
        if b < 0:
            raise ValueError("negative exponent")
        return a ** b

    def parse_expr():
        value = parse_term()
        while peek() in ("+", "-"):
            op = take()
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term():
        value = parse_unary()
        while peek() in ("*", "/", "%"):
            op = take()
            rhs = parse_unary()
            if op == "*":
                value = value * rhs
                continue
            if rhs == 0:
                raise ZeroDivisionError("division by zero")
            q = abs(value) // abs(rhs)
            if (value < 0) != (rhs < 0):
                q = -q
            value = q if op == "/" else value - rhs * q
        return value

    def parse_unary():
        negate = False
        while peek() == "-":
            take()
            negate = not negate
        value = parse_power()
        return -value if negate else value

    def parse_power():
        # power := primary ('^' unary)*, right-associative.
        # Handled iteratively so long chains do not hit the recursion limit.
        bases = [parse_primary()]
        signs = []
        while peek() == "^":
            take()
            neg = False
            while peek() == "-":
                take()
                neg = not neg
            signs.append(neg)
            bases.append(parse_primary())

        value = bases[-1]
        for j in range(len(bases) - 2, -1, -1):
            if signs[j]:
                value = -value
            value = power(bases[j], value)
        return value

    def parse_primary():
        if peek() == "(":
            take()
            value = parse_expr()
            if peek() == ")":
                take()
            return value
        return int(take())

    try:
        return parse_expr()
    except (ArithmeticError, ValueError):
        return "error"
